part.text:
The issue stems from incorrect usage of the database update syntax. The `db.update()` method requires the `.set()` chain before applying `where()`. Here's the fix:

**1. Fix `setStatus` function signature and logic:**
```typescript
function setStatus(id: number, status: 'fulfilled' | 'deleted', currentStatus: 'active' | 'fulfilled' | 'deleted' | 'expired') {
  const db = getDb();
  const validTransitions = {
    active: ['fulfilled', 'deleted'],
    fulfilled: ['deleted'],
    deleted: [],
    expired: []
  };

  if (!validTransitions[currentStatus].includes(status)) {
    throw new Error(`Cannot transition listing ${id} from ${currentStatus} to ${status}`);
  }

  return db.update(listings).set({ status, updatedAt: now() }).where(eq(listings.id, id)).run();
}
```

**2. Update `fulfillListing` and `softDeleteListing` to pass current status:**
```typescript
async function fulfillListing(id: number) {
  const listing = await getListingById(id);
  if (!listing) throw new Error(`Listing ${id} not found`);

  if (listing.status === 'deleted' || listing.status === 'expired') {
    throw new Error(`Cannot fulfill listing ${id} in status ${listing.status}`);
  }

  return setStatus(id, 'fulfilled', listing.status);
}

async function softDeleteListing(id: number) {
  const listing = await getListingById(id);
  if (!listing) throw new Error(`Listing ${id} not found`);

  if (listing.status === 'fulfilled' || listing.status === 'expired') {
    throw new Error(`Cannot delete listing ${id} in status ${listing.status}`);
  }

  return setStatus(id, 'deleted', listing.status);
}
```

**3. Add comprehensive tests in `listings.test.ts`:**
```typescript
test('fulfillListing updates status from active', async () => {
  const listing = await createListing({ status: 'active' });
  const updated = await fulfillListing(listing.id);
  expect(updated.status).toBe('fulfilled');
});

test('cannot fulfill deleted listing (invalid transition)', async () => {
  const listing = await createListing({ status: 'deleted' });
  await expect(fulfillListing(listing.id)).rejects.toThrow('Cannot fulfill listing');
});

test('cannot fulfill expired listing (invalid transition)', async () => {
  const listing = await createListing({ status: 'expired' });
  await expect(fulfillListing(listing.id)).rejects.toThrow('Cannot fulfill listing');
});

test('cannot delete fulfilled listing (invalid transition)', async () => {
  const listing = await createListing({ status: 'fulfilled' });
  await expect(softDeleteListing(listing.id)).rejects.toThrow('Cannot delete listing');
});

test('cannot delete expired listing (invalid transition)', async () => {
  const listing = await createListing({ status: 'expired' });
  await expect(softDeleteListing(listing.id)).rejects.toThrow('Cannot delete listing');
});
```

**4. Verify all tests pass:**
```bash
npx vitest run tests/services/listings.test.ts
```

The fix enforces status transition rules while maintaining the required behavior for valid transitions. The tests now accurately validate both allowed and forbidden transitions.
